// Locate a literal in its named constant/function and require its frozen hash.
// A changed source cannot teach the assertion to accept its new SQL.
func returnSQLSource(t *testing.T, file, symbol, digest string) string {
	t.Helper()
	root, err := parser.ParseFile(token.NewFileSet(), filepath.Join("..", file), nil, 0)
	returnPGOK(t, err)
	var found []string
	ast.Inspect(root, func(n ast.Node) bool {
		var target ast.Node
		switch n := n.(type) {
		case *ast.ValueSpec:
			if len(n.Names) == 1 && n.Names[0].Name == symbol {
				target = n
			}
		case *ast.FuncDecl:
			if n.Name.Name == symbol {
				target = n.Body
			}
		}
		if target != nil {
			ast.Inspect(target, func(n ast.Node) bool {
				if lit, ok := n.(*ast.BasicLit); ok && lit.Kind == token.STRING {
					sql, err := strconv.Unquote(lit.Value)
					returnPGOK(t, err)
					if fmt.Sprintf("%x", sha256.Sum256([]byte(sql))) == digest {
						found = append(found, sql)
					}
				}
				return true
			})
			return false
		}
		return true
	})
	if len(found) != 1 {
		t.Fatalf("reviewed SQL changed or missing: %s:%s (%d matches)", file, symbol, len(found))
	}
	return found[0]
}

// The same unchanged witness runs on the old helper and the correction. Child
// failures must be precisely the SQL rejection, never panic/timeout/other errors.
func TestReturnSQLRecorded(t *testing.T) {
	const childEnv = "SLG_RETURN_SQL_CHILD"
	var input struct {
		SQL    []string
		Pinned bool
	}
	p := freshsource.Profile{SchemaName: `return_SQL_"Q`}
	if os.Getenv(childEnv) == "1" {
		returnPGOK(t, json.NewDecoder(os.Stdin).Decode(&input))
		trace := &returnPGTrace{queries: []returnPGQuery{{sql: "begin isolation level read committed", pid: 17}}}
		for _, sql := range input.SQL {
			trace.queries = append(trace.queries, returnPGQuery{sql: sql, pid: 17})
		}
		trace.queries = append(trace.queries, returnPGQuery{sql: "rollback", pid: 17})
		returnPGRecorded(t, trace, p, input.Pinned)
		fmt.Println("RETURN_SQL_ACCEPTED")
		return
	}
	binary, err := os.Executable()
	returnPGOK(t, err)
	run := func(t *testing.T, queries []string, pinned bool, rejected string) {
		t.Helper()
		input.SQL, input.Pinned = queries, pinned
		body, err := json.Marshal(input)
		returnPGOK(t, err)
		ctx, cancel := context.WithTimeout(context.Background(), 15*time.Second)
		defer cancel()
		cmd := exec.CommandContext(ctx, binary, "-test.run=^TestReturnSQLRecorded$", "-test.count=1", "-test.timeout=10s")
		cmd.Env = append(os.Environ(), childEnv+"=1")
		cmd.Stdin = strings.NewReader(string(body))
		out, err := cmd.CombinedOutput()
		if ctx.Err() != nil {
			t.Fatalf("SQL witness timed out: %s", out)
		}
		if rejected == "" {
			if err != nil || string(out) != "RETURN_SQL_ACCEPTED\nPASS\n" {
				t.Fatalf("reviewed SQL rejected: %v\n%s", err, out)
			}
			return
		}
		diagnostic := fmt.Sprintf("unexpected validation SQL: %q", rejected)
		pattern := `\A--- FAIL: TestReturnSQLRecorded \([0-9.]+s\)\n    return_source_sql_test.go:[0-9]+: ` + regexp.QuoteMeta(diagnostic) + `\nFAIL\n\z`
		exit, ok := err.(*exec.ExitError)
		if !ok || exit.ExitCode() != 1 || !regexp.MustCompile(pattern).Match(out) {
			t.Fatalf("unsafe SQL was accepted or rejection was unrelated: %v\n%s", err, out)
		}
	}
	var reviewed []string
	for _, source := range returnSQLReviewed {
		sql := returnSQLSource(t, source.file, source.symbol, source.digest)
		reviewed = append(reviewed, sql)
		t.Run("accept/"+source.symbol, func(t *testing.T) { run(t, []string{sql}, false, "") })
	}
	sequence := "SELECT last_value,is_called FROM " + pgx.Identifier{p.SchemaName, "work_queue_id_seq"}.Sanitize()
	t.Run("accept/sequence", func(t *testing.T) { run(t, []string{sequence}, false, "") })
	// Independently enumerate the approved 12 pins, not the helper's inventory.
	pins := []struct{ table, prefix, mode string }{
		{"account", "LOCK TABLE ", "ROW SHARE"}, {"player", "LOCK TABLE ", "ROW SHARE"},
		{"player_wallet", "LOCK TABLE ", "ROW EXCLUSIVE"}, {"player_city", "LOCK TABLE ", "ROW SHARE"},
		{"mil_city_origin", "LOCK TABLE ONLY ", "ROW EXCLUSIVE"}, {"city_troop", "LOCK TABLE ONLY ", "ROW EXCLUSIVE"},
		{"work_queue", "LOCK TABLE ONLY ", "ROW EXCLUSIVE"}, {"mil_recruit_origin", "LOCK TABLE ONLY ", "ROW EXCLUSIVE"},
		{"mil_recruit_receipt", "LOCK TABLE ONLY ", "ROW EXCLUSIVE"}, {"march_order", "LOCK TABLE ONLY ", "ROW EXCLUSIVE"},
		{"field_army", "LOCK TABLE ONLY ", "ROW EXCLUSIVE"}, {"army_troop", "LOCK TABLE ONLY ", "ROW EXCLUSIVE"},
	}
	queries := []string{sequence}
	for _, pin := range pins {
		queries = append(queries, pin.prefix+pgx.Identifier{p.SchemaName, pin.table}.Sanitize()+" IN "+pin.mode+" MODE")
	}
	t.Run("accept/pins", func(t *testing.T) { run(t, queries, true, "") })
	for name, sql := range map[string]string{
		"cte_insert":           "WITH x AS (INSERT INTO player_wallet DEFAULT VALUES RETURNING *) SELECT * FROM x",
		"cte_update":           "WITH x AS (UPDATE player_wallet SET food=0 RETURNING *) SELECT * FROM x",
		"cte_delete":           "WITH x AS (DELETE FROM player_wallet RETURNING *) SELECT * FROM x",
		"cte_merge":            "WITH x AS (MERGE INTO player_wallet USING player ON false WHEN MATCHED THEN DELETE RETURNING *) SELECT * FROM x",
		"multiple":             "SELECT 1; UPDATE player_wallet SET food=0",
		"nextval_space":        "SELECT nextval ('work_queue_id_seq')",
		"nextval_newline":      "SELECT pg_catalog.nextval\n('work_queue_id_seq')",
		"nextval_comment":      "SELECT pg_catalog.nextval/**/('work_queue_id_seq')",
		"setval":               "SELECT pg_catalog.setval ('work_queue_id_seq',1)",
		"lock_update":          "SELECT * FROM player_wallet FOR UPDATE",
		"lock_no_key_update":   "SELECT * FROM player_wallet FOR NO KEY UPDATE",
		"lock_share":           "SELECT * FROM player_wallet FOR SHARE NOWAIT",
		"lock_key_share":       "SELECT * FROM player_wallet FOR KEY SHARE SKIP LOCKED",
		"unknown_read":         "SELECT 1",
		"function_write":       "SELECT pg_catalog.set_config('search_path','public',false)",
		"wrong_schema":         "SELECT last_value,is_called FROM " + pgx.Identifier{"other", "work_queue_id_seq"}.Sanitize(),
		"wrong_sequence":       "SELECT last_value,is_called FROM " + pgx.Identifier{p.SchemaName, "player_city_id_seq"}.Sanitize(),
		"unqualified_sequence": "SELECT last_value,is_called FROM work_queue_id_seq",
		"sequence_suffix":      sequence + "; DELETE FROM player_wallet",
		"catalog_suffix":       reviewed[0] + "; SELECT pg_catalog.nextval ('work_queue_id_seq')",
		"catalog_comment":      reviewed[0] + " -- unreviewed suffix",
		"wrong_pin_schema":     `LOCK TABLE "other"."account" IN ROW SHARE MODE`,
		"wrong_pin_mode":       strings.Replace(queries[1], "ROW SHARE", "ACCESS EXCLUSIVE", 1),
		"pin_suffix":           queries[1] + "; DELETE FROM player_wallet",
		"begin_suffix":         "begin isolation level read committed; DELETE FROM player_wallet",
		"rollback_suffix":      "rollback; DELETE FROM player_wallet",
		"empty":                " ",
	} {
		t.Run("reject/"+name, func(t *testing.T) { run(t, []string{sql}, false, sql) })
	}
}
